const fs = require('fs');

const quizData = {};

function createQuestions(quizNum, prefix, items) {
  return items.slice(0, 50).map((item, idx) => ({
    id: `${prefix}-${idx + 1}`,
    question: item.q,
    options: item.opts,
    correctIdx: item.correct !== undefined ? item.correct : 0,
    explanation: item.exp
  }));
}

